    "title": "Mental clutter",
    "subtitle": "একদিন ইমরান দলের বৈঠক-এ এমন একটি ভুল করল, যেটি পরে ভেবে তার নিজের কাছেই অদ্ভুত লাগল। ভুলটি ছিল না অজ্ঞতার ফল; বরং খুব দ্রুত পরিচিত shortcut বেছে নেওয়ার ফল। নিজের মাথার ভেতরের shortcut-টি দেখা গেল বলেই ভুলটি এবার শেখার উপ",
