        "id": "02",
        "title": "ধারণাটির ভেতরের কাঠামো",
        "blocks": [
          {
            "type": "paragraph",
            "content": "system-কে components, constraints, stakeholders ও sequence-এ ভাগ করা। এই chapter-এর কেন্দ্র। কথাটি শুনতে abstract লাগলেও এর ব্যবহারিক রূপ খুব স্পষ্ট: প্রথমে ঘটনার raw data আলাদা করো, তারপর নিজের interpretation লিখো, তারপর কোন rule বা assumption কাজ করছে তা খুঁজে বের করো। এই তিনটি স্তর একসঙ্গে লিখলে চিন্তা একটু ধীর হয়—আর সেই ধীরতার ভেতরেই choice দেখা যায়।"
          },
          {
            "type": "paragraph",
            "content": "বিষয়টি একটু ধীরে ধরলে ছবিটা পরিষ্কার হয়। মানুষ সাধারণত নিজের চিন্তাকে সরাসরি “সত্য” হিসেবে অনুভব করে। চিন্তা মাথায় এসেছে, তাই সেটি যেন বাস্তবতারই অংশ। অথচ চিন্তা অনেক সময় prediction, category, comparison বা emotional signal। এগুলো মূল্যবান; কিন্তু এগুলোকে যাচাই না করে final verdict বানালে problem তৈরি হয়।"
          }
        ]
