            "content": "একবার নিজের কথাটাই ভাবো: তুমি যখন বলো, “আমি জানি,” তখন সেই জানার ভিত্তি কী? সরাসরি দেখা? আগে শেখা তথ্য? কারও কথা? নাকি শুধু পরিচিত লাগছে? পরিচিত লাগা এবং সত্য হওয়া এক নয়। আবার সন্দেহ করলেই যে সত্য পাওয়া যায়, তাও নয়। Thinking-এর কাজ হলো confidence-কে evidence-এর সঙ্গে proportionate রাখা।"
