    "subtitle": "শিউলি সন্তানের পড়ার টেবিল-এ বসে ছিল। অভিভাবক হিসেবে সে নিজের কাজ জানে, নিজের অভ্যাসও জানে। তবু সেদিন একটি ছোট ঘটনায় তার পরিচিত ব্যাখ্যাটি একটু নড়ে গেল। সে বুঝল, সমস্যা সবসময় জ্ঞানের অভাব নয়; অনেক সময় সমস্যাটি হলো কোন তথ্",
