            "type": "paragraph",
            "content": "overconfidence, fluency, anchoring ও confirmation-এর self-monitoring। এই chapter-এর কেন্দ্র। কথাটি শুনতে abstract লাগলেও এর ব্যবহারিক রূপ খুব স্পষ্ট: প্রথমে ঘটনার raw data আলাদা করো, তারপর নিজের interpretation লিখো, তারপর কোন rule বা assumption কাজ করছে তা খুঁজে বের করো। এই তিনটি স্তর একসঙ্গে লিখলে চিন্তা একটু ধীর হয়—আর সেই ধীরতার ভেতরেই choice দেখা যায়।"
