    "title": "Confirmation bias",
    "subtitle": "ঘটনাটি খুব সাধারণ। মেহরিন স্টাফরুম-এ একটি সিদ্ধান্ত নিতে গিয়ে প্রথম যে উত্তরটি মাথায় এলো, সেটিই ধরে রাখতে চেয়েছিল। উত্তরটি ভুল ছিল না; কিন্তু সেটি অসম্পূর্ণ ছিল। এখানেই confirmation bias-এর আসল প্রশ্ন: আমরা কি উত্তর খুঁজ",
    "readingMinutes": 7,
